@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        ApplicationContext context = SpringApplication.run(DemoApplication.class, args);

        NotificationService service = context.getBean(NotificationService.class);
        service.notifyCustomer("amy@example.com", "Hello!");

        NotificationService sameService = context.getBean(NotificationService.class);
        System.out.println(service == sameService);   // true
    }
}

@Service
public class RequestCounter {
    private int count = 0;   // one shared field, one shared bean instance

    public int increment() {
        count = count + 1;
        return count;
    }
}

// Two concurrent HTTP requests both call:
// counter.increment();
// Both requests hit the exact same RequestCounter instance and the exact same count field.

